solution:
inventory = {
  'SKU101': {'name': 'Laptop Charger', 'stock': 12, 'tags': {'electronics', 'accessories', 'power'}},
  'SKU102': {'name': 'Ergonomic Mouse', 'stock': 5, 'tags': {'electronics', 'peripherals', 'input'}},
  'SKU103': {'name': 'Monitor Stand', 'stock': 15, 'tags': {'ergonomics', 'office', 'furniture'}}
}
REQUIRED_TAGS = {'accessories', 'office', 'power', 'input', 'electronics'}

all_inventory_tags = set()

# 1. Iterate over inventory:
for sku, details in inventory.items():
    # 2. Check for low stock:
    if details['stock'] < 10:
        print(f'LOW STOCK ALERT: {sku} ({details["stock"]} remaining)')

    # 3. Find missing tags (Difference):
    missing_tags = REQUIRED_TAGS - details['tags']
    if missing_tags:
        print(f'{sku}: Missing required tags: {missing_tags}')

    # 4. Consolidate all tags (Union):
    all_inventory_tags = all_inventory_tags | details['tags']


# 5. Print final summary:
print(f'\n--- FINAL SUMMARY ---\nAll Unique Tags: {all_inventory_tags}')
